package com.bank.qa.coverage;

import java.util.*;

// Toy tracker: records which "branch ids" tests actually exercised.
class CoverageTracker {
    static final Set<String> HIT = new HashSet<>();
    static void hit(String branchId) { HIT.add(branchId); }
    static double branchCoveragePct(Set<String> allBranches) {
        long covered = allBranches.stream().filter(HIT::contains).count();
        return 100.0 * covered / allBranches.size();
    }
}
