package com.bank.qa.coverage;

import java.math.BigDecimal;

// Branchy fee logic. Each branch is tagged so we can see what tests hit.
class FeeCalculator {
    static final java.util.Set<String> BRANCHES =
        java.util.Set.of("B_PREMIUM_WAIVER", "B_SMALL_FLAT", "B_STANDARD_PCT");

    BigDecimal fee(BigDecimal amount, boolean premium) {
        if (premium) {                              // critical branch (waiver)
            CoverageTracker.hit("B_PREMIUM_WAIVER");
            return BigDecimal.ZERO;                  // premium customers pay no fee
        }
        if (amount.compareTo(new BigDecimal("1000")) < 0) {
            CoverageTracker.hit("B_SMALL_FLAT");
            return new BigDecimal("10.00");          // flat fee for small amounts
        }
        CoverageTracker.hit("B_STANDARD_PCT");
        return amount.multiply(new BigDecimal("0.01")) // 1% standard fee
                     .setScale(2, java.math.RoundingMode.HALF_UP);
    }
}
