package com.bank.qa.coverage;

import java.math.BigDecimal;
import java.util.logging.*;

public class CoverageDemo {
    private static final Logger log = Logger.getLogger(CoverageDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new CovLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        FeeCalculator calc = new FeeCalculator();

        log.info("=== WEAK suite: high LINE coverage but misses the premium waiver branch ===");
        // These two tests execute most lines, but NEVER the premium=true branch.
        log.info("fee(500,false) = " + calc.fee(new BigDecimal("500"), false));     // small flat
        log.info("fee(100000,false) = " + calc.fee(new BigDecimal("100000"), false)); // standard %
        log.info(String.format("branch coverage so far = %.0f%% (critical waiver UNTESTED)",
            CoverageTracker.branchCoveragePct(FeeCalculator.BRANCHES)));

        log.info("=== Add the MEANINGFUL test for the risky branch ===");
        log.info("fee(100000,true) = " + calc.fee(new BigDecimal("100000"), true));  // premium waiver
        log.info(String.format("branch coverage now = %.0f%%",
            CoverageTracker.branchCoveragePct(FeeCalculator.BRANCHES)));

        log.info("Lesson: line coverage looked fine, but the waiver branch — where a "
            + "wrong fee hits a premium customer — was untested. Cover IMPORTANT logic, "
            + "not a 100% vanity number.");
    }
}

// ─── Would be in CovLogFormatter.java in a real project ───
class CovLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
